                        if (serverBusy[qi] > cust2.arrival) effLen++;
                        if (effLen < shortestLen) {
                            shortestLen = effLen;
                            shortestQ = qi;
                        }
                    }

                    var startT2;
                    if (serverBusy[shortestQ] <= cust2.arrival) {
                        startT2 = cust2.arrival;
                    } else {
                        startT2 = serverBusy[shortestQ];
                    }
                    var wt2 = startT2 - cust2.arrival;
                    serverBusy[shortestQ] = startT2 + cust2.serviceTime;
                    totalBusy += cust2.serviceTime;
                    queues[shortestQ].push(startT2 + cust2.serviceTime);
                    if (ci2 >= WARMUP) waitTimes.push(wt2);
                }
            } else {
                var typeQueues = { A: [], B: [], C: [] };
                var typeServers = {};

                if (numServers === 1) {
                    typeServers = { A: [0], B: [0], C: [0] };
                } else if (numServers === 2) {
                    typeServers = { A: [0], B: [0, 1], C: [1] };
                } else {
                    typeServers = { A: [0], B: [1], C: [2] };
                }

                for (var ci3 = 0; ci3 < customers.length; ci3++) {
                    var cust3 = customers[ci3];
                    var allowedServers = typeServers[cust3.type];
                    var bestServer = allowedServers[0];
                    var bestFinish = serverBusy[allowedServers[0]];
                    for (var as = 1; as < allowedServers.length; as++) {
                        if (serverBusy[allowedServers[as]] < bestFinish) {
                            bestFinish = serverBusy[allowedServers[as]];
                            bestServer = allowedServers[as];
                        }
                    }

                    var startT3;
                    if (serverBusy[bestServer] <= cust3.arrival) {
                        startT3 = cust3.arrival;
                    } else {
                        startT3 = serverBusy[bestServer];
                    }
                    var wt3 = startT3 - cust3.arrival;
                    serverBusy[bestServer] = startT3 + cust3.serviceTime;
                    totalBusy += cust3.serviceTime;
                    if (ci3 >= WARMUP) waitTimes.push(wt3);
                }
            }

            waitTimes.sort(function(a, b) { return a - b; });
            var n = waitTimes.length;
            if (n === 0) return null;

            var meanWait = waitTimes.reduce(function(s, v) { return s + v; }, 0) / n;
            var p50 = waitTimes[Math.floor(n * 0.5)];
            var p90 = waitTimes[Math.floor(n * 0.9)];
            var p95 = waitTimes[Math.min(Math.floor(n * 0.95), n - 1)];

            var lastDepart = 0;
            for (var fs = 0; fs < numServers; fs++) {
                if (serverBusy[fs] > lastDepart) lastDepart = serverBusy[fs];
            }
            var simDuration = lastDepart - customers[WARMUP].arrival;
            var utilization = totalBusy / (numServers * simDuration);
            utilization = Math.min(utilization, 0.99);

            var throughput = n / simDuration;

            var pctC = Math.max(0, 100 - pctA - pctB);
            var weightedMeanService = (pctA / 100) * 0.12 + (pctB / 100) * 0.22 + (pctC / 100) * 0.48;

            var cvArrMap = { low: 0.577, medium: 1.0, high: 2.0 };
            var cvSvcMap = { low: 0.577, medium: 1.0, high: 2.0 };
            var cva2 = Math.pow(cvArrMap[arrivalVar] || 1.0, 2);
            var cvs2 = Math.pow(cvSvcMap[serviceVar] || 1.0, 2);

            var rhoEff = utilization;
            var kingmanWait = ((cva2 + cvs2) / 2) * (rhoEff / (1 - rhoEff)) * weightedMeanService;
            if (numServers > 1) {
                kingmanWait = kingmanWait / numServers;
            }

            return {
                meanWait: Math.round(meanWait * 1000) / 1000,
                p50: Math.round(p50 * 1000) / 1000,
                p90: Math.round(p90 * 1000) / 1000,
                p95: Math.round(p95 * 1000) / 1000,
                utilization: Math.round(utilization * 1000) / 1000,
                throughput: Math.round(throughput * 100) / 100,
                avgQueueLen: Math.round(meanWait * lambda * 10) / 10,
                customersServed: n,
                kingmanWait: Math.round(kingmanWait * 1000) / 1000,
                cva2: cva2,
                cvs2: cvs2,
                rho: rhoEff,
                meanServiceTime: weightedMeanService
            };
        }

        // ---- assessment (1.2.0). Sources: TN 12 debrief map and 7 Q1-Q4 (one lever per comparison, matched load),
        // case Process Background (current branch design: type-dedicated queues, arrival CV 1.1, nearest level Medium),
        // case Industry and Market Context (above 85 percent utilization the variability term dominates).
        _offeredLoad(d) {
            var a = Number(d.pctTypeA) || 0, b = Number(d.pctTypeB) || 0, c = Math.max(0, 100 - a - b);
            var es = (a / 100) * this.CUSTOMER_TYPES.A.meanService + (b / 100) * this.CUSTOMER_TYPES.B.meanService + (c / 100) * this.CUSTOMER_TYPES.C.meanService;
            var ns = Number(d.numServers) || 1;
            return Math.round((Number(d.arrivalRate) || 0) * es / ns * 1000) / 1000;
        }

        _hashStr(s) {
            var h = 2166136261;
            for (var i = 0; i < s.length; i++) { h ^= s.charCodeAt(i); h = Math.imul(h, 16777619); }
            return h >>> 0;
        }

        _medianP90(d, reps) {
            var own = Math.random, out = [], self = this;
            try {
                for (var r = 0; r < reps; r++) {
                    var a = this._hashStr('105|' + d.numServers + '|' + d.arrivalRate + '|' + d.serviceVar + '|' + d.pctTypeA + '|' + d.pctTypeB + '|' + r) | 0;
                    Math.random = function () {
                        a = (a + 0x6D2B79F5) | 0;
                        var t = Math.imul(a ^ (a >>> 15), 1 | a);
                        t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
                        return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
                    };
                    var res = self._runSimulation(d);
                    out.push(res ? res.p90 : 0);
                }
            } finally { Math.random = own; }
            out.sort(function (x, y) { return x - y; });
            return out[Math.floor(out.length / 2)];
        }

        _logEntry(d, sim) {
            var e = {
                ns: Number(d.numServers), qd: d.queueDiscipline, ar: Number(d.arrivalRate), av: d.arrivalVar, sv: d.serviceVar,
                a: Number(d.pctTypeA) || 0, b: Number(d.pctTypeB) || 0, p90: sim ? sim.p90 : 0, rho: this._offeredLoad(d)
            };
            var bench = { numServers: e.ns, queueDiscipline: 'dedicated', arrivalRate: e.ar, arrivalVar: 'medium', serviceVar: e.sv, pctTypeA: e.a, pctTypeB: e.b };
            if (e.rho < 1) {
                e.p90c = Math.round(this._medianP90(d, 5) * 1000) / 1000;
                e.p90b = Math.round(this._medianP90(bench, 5) * 1000) / 1000;
            } else { e.p90c = null; e.p90b = null; }
            return e;
        }

        _same(x, y, skip) {
            var keys = ['ns', 'qd', 'ar', 'av', 'sv', 'a', 'b'];
            for (var i = 0; i < keys.length; i++) {
                if (skip.indexOf(keys[i]) >= 0) { continue; }
                if (String(x[keys[i]]) !== String(y[keys[i]])) { return false; }
            }
            return true;
        }

        _mixOk(e) { return e.a >= 10 && e.b >= 10 && (100 - e.a - e.b) >= 10; }

        _evaluate(log) {
            log = Array.isArray(log) ? log : [];
            var f = { load: false, pool: false, varIso: false, arrIso: false, mix: false, serversVaried: false };
            var i, j;
            for (i = 0; i < log.length; i++) {
                var x = log[i];
                if (x.rho >= 0.85 && x.rho < 1) { f.load = true; }
                for (j = 0; j < i; j++) {
                    var y = log[j];
                    if (x.ns !== y.ns) { f.serversVaried = true; }
                    if (x.ns >= 2 && x.qd !== y.qd && this._same(x, y, ['qd'])) { f.pool = true; }
                    if (x.av !== y.av && this._same(x, y, ['av'])) { f.varIso = true; f.arrIso = true; }
                    if (x.sv !== y.sv && this._same(x, y, ['sv'])) { f.varIso = true; }
                }
            }
            for (i = 0; i < log.length && !f.mix; i++) {
                if (log[i].ns !== 3 || !this._mixOk(log[i])) { continue; }
                var seen = {};
                for (j = 0; j < log.length; j++) { if (this._same(log[i], log[j], ['qd'])) { seen[log[j].qd] = true; } }
                if (seen.pooled && seen.separate && seen.dedicated) { f.mix = true; }
            }
            var process = (f.load ? 15 : 0) + (f.pool ? 15 : 0) + (f.varIso ? 15 : 0) + (f.mix ? 15 : 0);
            var last = log.length ? log[log.length - 1] : null, outcome = 0, gain = 0, lf = 0;
            var commit = { overload: false, mixOk: false, gain: 0, lf: 0 };
            if (last) {
                commit.mixOk = this._mixOk(last);
                commit.overload = !(last.rho < 1);
                lf = commit.overload ? 0 : Math.max(0, Math.min(1, (last.rho - 0.4) / 0.35));
                if (!commit.overload && last.p90b > 0) { gain = Math.max(0, Math.min(1, 1 - last.p90c / last.p90b)); }
                commit.gain = gain; commit.lf = lf;
                outcome = commit.mixOk ? 40 * lf * gain : 0;
            }
            var total = Math.max(0, Math.min(100, Math.round(process + outcome)));
            return { flags: f, process: process, outcome: Math.round(outcome * 10) / 10, total: total, last: last, commit: commit };
        }

        _tier(score) {
            if (score >= 80) { return 'excellent'; }
            if (score >= 60) { return 'good'; }
            if (score >= 40) { return 'developing'; }
            return 'beginner';
        }

        calculateResults(state) {
            var d = state.decisions;
            var simResult = this._runSimulation(d);

            if (!simResult) {
                return {
                    period: state.currentPeriod,
                    error: true,
                    meanWait: 0, p50: 0, p90: 0, p95: 0,
                    utilization: 0, throughput: 0, avgQueueLen: 0, customersServed: 0,
                    kingmanWait: 0, numServers: d.numServers,
                    queueDiscipline: d.queueDiscipline
                };
            }

            state.domainState.experimentsRun++;
            state.domainState.lastUtilization = simResult.utilization;
            state.domainState.lastP90 = simResult.p90;
            if (state.domainState.bestP90 === null || simResult.p90 < state.domainState.bestP90) {
                state.domainState.bestP90 = simResult.p90;
            }

            state.domainState.p90History.push(simResult.p90);
            state.domainState.utilizationHistory.push(simResult.utilization);
            state.domainState.meanWaitHistory.push(simResult.meanWait);
            state.domainState.p50History.push(simResult.p50);
            state.domainState.p95History.push(simResult.p95);

            // platform score (1.2.0): protocol plus recommendation, from one helper shared with the end screen.
            // The assessment replications use their own seeded generator, so the experiment draws above are unchanged.
            var entry = this._logEntry(d, simResult);
            if (!Array.isArray(state.domainState.log)) { state.domainState.log = []; }
            state.domainState.log.push(entry);
            var ev = this._evaluate(state.domainState.log);
            var overallScore = ev.total;
            state.domainState.performance = Object.assign({}, state.domainState.performance || {}, {
                overallScore: overallScore, processScore: ev.process, outcomeScore: ev.outcome, tier: this._tier(overallScore)
            });
            state.domainState.performanceTier = this._tier(overallScore);

            var results = {
                period: state.currentPeriod,
                numServers: d.numServers,
                queueDiscipline: d.queueDiscipline,
                arrivalRate: d.arrivalRate,
                arrivalVar: d.arrivalVar,
                serviceVar: d.serviceVar,
                pctTypeA: d.pctTypeA,
                pctTypeB: d.pctTypeB,
                meanWait: simResult.meanWait,
                p50: simResult.p50,
                p90: simResult.p90,
                p95: simResult.p95,
                utilization: simResult.utilization,
                throughput: simResult.throughput,
                avgQueueLen: simResult.avgQueueLen,
                customersServed: simResult.customersServed,
                kingmanWait: simResult.kingmanWait,
                cva2: simResult.cva2,
                cvs2: simResult.cvs2,
                rho: simResult.rho,
                meanServiceTime: simResult.meanServiceTime,
                offeredLoad: entry.rho,
                assessP90: entry.p90c,
                benchP90: entry.p90b,
                processScore: ev.process,
                outcomeScore: ev.outcome,
                overallScore: overallScore,
                score: overallScore,
                totalScore: overallScore
            };

            var self = this;
            setTimeout(function() {
                self._showResults(results);
            }, 300);

            return results;
        }

        _showResults(r) {
            var panel = document.getElementById('resultsPanel');
            if (panel) panel.style.display = 'block';

            var el;
