        _t(key, vars) {
            var out = key;
            try { if (window.mySimulation && typeof window.mySimulation.t === 'function') { out = window.mySimulation.t(key); } } catch (e) {}
            if (vars) { for (var k in vars) { if (Object.prototype.hasOwnProperty.call(vars, k)) { out = String(out).split('{' + k + '}').join(vars[k]); } } }
            return out;
        }

        _lang() {
            var l = '';
            try { if (window.vcI18n && window.vcI18n._lang) { l = window.vcI18n._lang; } } catch (e) {}
            if (!l) { l = (document.documentElement && document.documentElement.lang) || 'en'; }
            return String(l).toLowerCase().slice(0, 2);
        }

        _num(v, dp) {
            var s = (Number(v) || 0).toFixed(dp);
            return this._lang() === 'es' ? s.replace('.', ',') : s;
        }

        _logFromHistory(history) {
            var out = [];
            for (var i = 0; i < history.length; i++) {
                var r = history[i] && history[i].results;
                if (!r || r.error) { continue; }
                out.push({ ns: Number(r.numServers), qd: r.queueDiscipline, ar: Number(r.arrivalRate), av: r.arrivalVar, sv: r.serviceVar,
                    a: Number(r.pctTypeA) || 0, b: Number(r.pctTypeB) || 0, p90: Number(r.p90) || 0, u: Number(r.utilization) || 0,
                    rho: typeof r.offeredLoad === 'number' ? r.offeredLoad : this._offeredLoad(r),
                    p90c: r.assessP90 === undefined ? null : r.assessP90, p90b: r.benchP90 === undefined ? null : r.benchP90 });
            }
            return out;
        }

        _changed(x, y) {
            var names = { ns: 'lev_servers', qd: 'lev_disc', ar: 'lev_rate', av: 'lev_avar', sv: 'lev_svar', a: 'lev_mix', b: 'lev_mix' }, out = [];
            for (var k in names) {
                if (String(x[k]) !== String(y[k])) { var lab = this._t(names[k]); if (out.indexOf(lab) < 0) { out.push(lab); } }
            }
            return out;
        }

        getPerformanceSummary(history) {
            if (!history || !history.length) { return {}; }
            var log = this._logFromHistory(history);
            if (!log.length) { return {}; }
            var ev = this._evaluate(log), f = ev.flags, c = ev.commit, last = ev.last;
            var p90s = log.map(function (e) { return e.p90; });
            var bestP90 = Math.min.apply(null, p90s);
            var tier = this._tier(ev.total);
            var insights = [];
            if (!c.mixOk) { insights.push(this._t('ins_mix_missing')); }
            else if (c.overload) { insights.push(this._t('ins_overload')); }
            else if (last.qd === 'dedicated') { insights.push(this._t('ins_specialised')); }
            else { insights.push(this._t('ins_design', { pct: this._num(c.gain * 100, 0) })); }
            if (!f.load) { insights.push(this._t('ins_light_load')); }
            if (!f.pool) { insights.push(this._t(f.serversVaried ? 'ins_capacity' : 'ins_no_pool')); }
            if (!f.arrIso) { insights.push(this._t('ins_arrival_untested')); }
            if (f.load && f.pool && f.varIso && f.mix) { insights.push(this._t('ins_protocol_full')); }
            else if (!f.mix) { insights.push(this._t('ins_no_mix')); }
            // what the student measured: the first matched discipline pair and the first arrival-variability pair
            var poolPair = null, varPair = null, qi, qj;
            for (qi = 0; qi < log.length; qi++) {
                for (qj = 0; qj < qi; qj++) {
                    if (log[qi].ns >= 2 && log[qi].qd !== log[qj].qd && this._same(log[qi], log[qj], ['qd']) && (!poolPair || (poolPair[0].qd !== 'pooled' && poolPair[1].qd !== 'pooled'))) { poolPair = [log[qj], log[qi]]; }
                    if (!varPair && log[qi].av !== log[qj].av && this._same(log[qi], log[qj], ['av'])) { varPair = [log[qj], log[qi]]; }
                }
            }
            if (poolPair) {
                insights.push(this._t('ins_pool_measured', { n: String(poolPair[0].ns), q1: this._t('opt_' + poolPair[0].qd), a: this._num(poolPair[0].p90, 2), q2: this._t('opt_' + poolPair[1].qd), b: this._num(poolPair[1].p90, 2) }));
            }
            if (varPair) {
                insights.push(this._t('ins_var_measured', { v1: this._t('opt_' + varPair[0].av), v2: this._t('opt_' + varPair[1].av), a: this._num(varPair[0].p90, 2), b: this._num(varPair[1].p90, 2),
                    u1: this._num(varPair[0].u * 100, 0), u2: this._num(varPair[1].u * 100, 0) }));
            }
            insights = insights.slice(0, 5);
            // turning point: the largest P90 move between consecutive experiments, and what changed
            // a one-lever change is preferred; several levers at once only when no single-lever change exists
            var tp = null, big = -1, tpAny = null, bigAny = -1;
            for (var i = 1; i < log.length; i++) {
                var dlt = Math.abs(log[i].p90 - log[i - 1].p90);
                if (dlt > bigAny) { bigAny = dlt; tpAny = i; }
                if (this._changed(log[i], log[i - 1]).length === 1 && dlt > big) { big = dlt; tp = i; }
            }
            if (tp === null) { tp = tpAny; }
            var turning = '';
            if (tp !== null) {
                var ch = this._changed(log[tp], log[tp - 1]);
                turning = ch.length ? this._t(ch.length > 1 ? 'tp_many' : 'tp_one', { n: String(tp + 1), levers: ch.join(', '), from: this._num(log[tp - 1].p90, 2), to: this._num(log[tp].p90, 2) })
                    : this._t('tp_repeat', { n: String(tp + 1), from: this._num(log[tp - 1].p90, 2), to: this._num(log[tp].p90, 2) });
            }
            return {
                performance: tier,
                performanceKey: 'tier_' + tier,
                performanceLabel: this._t('tier_' + tier),
                overallScore: ev.total, composite: ev.total, totalScore: ev.total, score: ev.total,
                processScore: ev.process, outcomeScore: ev.outcome,
                experimentsRun: log.length,
                bestP90: bestP90,
                commitP90: last.p90c, benchP90: last.p90b, commitLoad: last.rho,
                flags: f,
                turningPoint: turning,
                insights: insights
            };
        }

        formatCompletionMessage(summary) {
            summary = summary || {};
            if (summary.overallScore === undefined) { return '<div class="queuelab-sim-debrief"><p>' + this._t('db_none') + '</p></div>'; }
            var self = this, f = summary.flags || {};
            function row(ok, key) { return '<li>' + (ok ? '&#10003; ' : '&#10007; ') + '<span class="queuelab-sim-db-' + (ok ? 'ok' : 'miss') + '">' + self._t(ok ? 'db_done' : 'db_missing') + '</span>: ' + self._t(key) + '</li>'; }
            var p90c = summary.commitP90 === null || summary.commitP90 === undefined ? '--' : this._num(summary.commitP90, 2);
            var p90b = summary.benchP90 === null || summary.benchP90 === undefined ? '--' : this._num(summary.benchP90, 2);
            var h = '<div class="queuelab-sim-debrief">';
            h += '<h3>' + this._t('db_heading') + '</h3>';
            h += '<p class="queuelab-sim-db-score"><strong>' + summary.overallScore + '/100</strong> &middot; ' + summary.performanceLabel + '</p>';
            h += '<p>' + this._t('db_subscores', { p: String(summary.processScore), o: this._num(summary.outcomeScore, 1) }) + '</p>';
            h += '<ul class="queuelab-sim-db-kpis">';
            h += '<li>' + this._t('db_kpi_runs', { n: String(summary.experimentsRun) }) + '</li>';
            h += '<li>' + this._t('db_kpi_best', { v: this._num(summary.bestP90, 2) }) + '</li>';
            h += '<li>' + this._t('db_kpi_commit', { c: p90c, b: p90b, l: this._num((summary.commitLoad || 0) * 100, 0) }) + '</li>';
            h += '</ul>';
            h += '<h4>' + this._t('db_protocol') + '</h4><ul class="queuelab-sim-db-check">';
            h += row(!!f.load, 'chk_load') + row(!!f.pool, 'chk_pool') + row(!!f.varIso, 'chk_var') + row(!!f.mix, 'chk_mix');
            h += '</ul>';
            if (summary.turningPoint) { h += '<h4>' + this._t('db_turning') + '</h4><p>' + summary.turningPoint + '</p>'; }
            h += '<h4>' + this._t('db_insights') + '</h4><ul>';
            for (var i = 0; i < (summary.insights || []).length; i++) { h += '<li>' + summary.insights[i] + '</li>'; }
            h += '</ul><h4>' + this._t('db_questions') + '</h4><ol>';
            h += '<li>' + this._t('dq_1') + '</li><li>' + this._t('dq_2') + '</li><li>' + this._t('dq_3') + '</li>';
            h += '</ol></div>';
            return h;
        }

        getHint(state, results) {
            if (!results || results.error) return null;

            if (results.utilization > 0.92) {
                return window.mySimulation.t('hint_high_util');
            }
            if (results.p90 > 3 && results.queueDiscipline !== 'pooled') {
                return window.mySimulation.t('hint_try_pooled');
            }
            if (results.p90 > 2 && results.numServers < 3) {
                return window.mySimulation.t('hint_add_server');
            }
            if (results.p95 > results.p50 * 5) {
                return window.mySimulation.t('hint_tail');
            }
            if (results.utilization < 0.5 && results.numServers > 1) {
                return window.mySimulation.t('hint_over_capacity');
            }
            if (results.p90 < 0.5) {
                return window.mySimulation.t('hint_great');
            }
            return null;
        }

